package markdown

import (
	"fmt"
	"strings"
)

// Render translates markdown to HTML.
//
// Refactoring notes:
// The original implementation processed the document one character at a time
// in a single loop, tracking a header level, a list counter, a listOpened
// flag, and a "header ended" flag to decide how to treat '#', '*', and '_'
// characters. The control flow was hard to follow and several branches only
// made sense in combination with the others.
//
// The rewrite splits the work into two clear phases:
//  1. applyEmphasis rewrites the first __...__ and _..._ pairs into HTML
//     tags across the whole document, exactly as the original did.
//  2. The document is then rendered line by line. Each line is one of three
//     blocks: a header (1-6 leading '#'), a list item (leading "* "), or a
//     paragraph. A line that is not a list item closes any open list.
func Render(markdown string) string {
	markdown = applyEmphasis(markdown)

	var b strings.Builder
	inList := false
	for _, line := range strings.Split(markdown, "\n") {
		if level, text, ok := header(line); ok {
			if inList {
				b.WriteString("</li></ul>")
				inList = false
			}
			fmt.Fprintf(&b, "<h%d>%s</h%d>", level, text, level)
		} else if text, ok := listItem(line); ok {
			if inList {
				b.WriteString("</li>")
			} else {
				b.WriteString("<ul>")
				inList = true
			}
			b.WriteString("<li>" + text)
		} else {
			if inList {
				b.WriteString("</li></ul>")
				inList = false
			}
			b.WriteString("<p>" + line + "</p>")
		}
	}
	if inList {
		b.WriteString("</li></ul>")
	}
	return b.String()
}

// applyEmphasis replaces the first "__" pair with <strong> tags and the
// first single "_" pair with <em> tags, mirroring the original behavior.
// It runs before block parsing so that emphasis works inside headers, list
// items, and paragraphs alike.
func applyEmphasis(markdown string) string {
	markdown = strings.Replace(markdown, "__", "<strong>", 1)
	markdown = strings.Replace(markdown, "__", "</strong>", 1)
	markdown = strings.Replace(markdown, "_", "<em>", 1)
	markdown = strings.Replace(markdown, "_", "</em>", 1)
	return markdown
}

// header reports whether line starts with a header marker, i.e. 1 to 6
// leading '#' characters (7 or more is treated as plain text, matching the
// "h7 header level is a paragraph" test case). It returns the header level
// and the text following the marker; '#' and '*' characters in that text
// are kept verbatim.
func header(line string) (level int, text string, ok bool) {
	for level < len(line) && line[level] == '#' {
		level++
	}
	if level == 0 || level > 6 {
		return 0, "", false
	}
	text = line[level:]
	if strings.HasPrefix(text, " ") {
		text = text[1:]
	}
	return level, text, true
}

// listItem reports whether line starts with a "* " bullet and returns the
// text of the item; markdown symbols in that text are kept verbatim.
func listItem(line string) (string, bool) {
	if !strings.HasPrefix(line, "* ") {
		return "", false
	}
	return line[2:], true
}

